import math

def combinations(n, k):
    if k < 0 or k > n:
        return 0
    if k == 0 or k == n:
        return 1
    if k > n // 2:
        k = n - k

    res = 1
    for i in range(k):
        res = res * (n - i) // (i + 1)
    return res

def f_kn(n):
    # Number of triangles C_3: binomial(n, 3)
    return combinations(n, 3)

def g_kn(n):
    # Number of cycles of length 4 C_4: 3 * binomial(n, 4)
    if n < 4:
        return 0
    return 3 * combinations(n, 4)

ratios = {}
for n in range(4, 9):
    f = f_kn(n)
    g = g_kn(n)

    # Calculate the ratio g(K_n)^3 / f(K_n)^4
    # Since f(K_n) is generally non-zero for n >= 3, and g(K_n) is non-zero for n >= 4, 
    # we proceed with the division.

    if f == 0:
        ratio = None # Should not happen for n >= 4
    else:
        ratio = (g**3) / (f**4)

    ratios[n] = ratio

print("Ratios g(K_n)^3 / f(K_n)^4 for n=4 to 8:")
for n, ratio in ratios.items():
    print(f"n={n}: {ratio}")

import math

def calculate_r(N):
    # f(K_N) = C(N, 3)
    f_kN = math.comb(N, 3)
    # g(K_N) = C(N, 4)
    g_kN = math.comb(N, 4)

    if f_kN == 0:
        return float('inf') if g_kN > 0 else 0

    return (g_kN**3) / (f_kN**4)

results = {}
for N in [4, 5, 6, 7]:
    results[N] = calculate_r(N)

print(results)
